import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    teacher_hint = torch.randn(3, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(inputs), "teacher_hint": synth.Tensor(teacher_hint)}
dataset = synth.Spec("fitnets-hints", generator=samples, size=12, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class StudentWithRegressor(nn.Module):
    def __init__(self):
        super().__init__()
        self.guided = build("mlp", "tiny", in_features=4, out_features=2)
        self.regressor = nn.Linear(2, 3)
    def forward(self, inputs):
        return {"hint": self.regressor(self.guided(inputs))}
trainer = Trainer(StudentWithRegressor(), train, recipe="structured-objective", recipe_config={"loss": "fitnets", "bindings": {"logits_or_prediction": {"output": "hint"}, "targets": {"batch": "teacher_hint"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
